package main

import "github.com/hectorgimenez/d2go/pkg/data/item"

// d2go's item table predates D2R 3.3, which inserted new items, so its classID -> name
// lookup is off for everything after the first insertion (a Town Portal scroll reads as
// "TheBlackTowerKey"). classCodes (generated by build-observe.mjs from the repo's
// data/txt, which tracks the live game) gives the item code for each classID; the code
// then maps back to d2go's CamelCase name, which the grader expects.
var nameByCode = func() map[string]item.Name {
	m := make(map[string]item.Name, len(item.Desc))
	for id, d := range item.Desc {
		if d.Code != "" {
			m[d.Code] = item.GetNameByEnum(uint(id))
		}
	}
	return m
}()

// itemName returns the item's name for this game build, falling back to d2go's guess.
func itemName(classID int, fallback item.Name) string {
	if classID >= 0 && classID < len(classCodes) {
		if n, ok := nameByCode[classCodes[classID]]; ok {
			return string(n)
		}
		if classCodes[classID] != "" {
			return classCodes[classID] // a 3.3 item d2go has never heard of
		}
	}
	return string(fallback)
}
